<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Delete, Edit, Plus, Refresh } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { apiErrorMessage } from '../../../api/error'
import { createReleaseDrill, createReleaseDrillStep, deleteReleaseDrill, deleteReleaseDrillStep, listReleaseDrillEnvironments, listReleaseOperationMemberOptions, listReleasePlans, listReleaseDrills, updateReleaseDrill, updateReleaseDrillStep, type ReleaseDrillEnvironmentDto, type ReleaseDrillExecutionDto, type ReleaseDrillExecutionWrite, type ReleaseDrillStepDto, type ReleaseMemberOptionDto, type ReleasePlanDto } from '../../../api/release'
import { useAuthStore } from '../../../stores/auth'
import UiEmptyState from '../../../components/ui/UiEmptyState.vue'
import UiStatusTag from '../../../components/ui/UiStatusTag.vue'

const props = defineProps<{ projectId: number }>()
const auth = useAuthStore(); const rounds = ref<ReleaseDrillExecutionDto[]>([]); const plans = ref<ReleasePlanDto[]>([]); const environments = ref<ReleaseDrillEnvironmentDto[]>([]); const members = ref<ReleaseMemberOptionDto[]>([]); const selectedId = ref<number>(); const loading = ref(false); const error = ref(''); const forbidden = ref(false); const saving = ref(false); const stepSaving = ref(false); const roundDialog = ref(false); const stepDrawer = ref(false); const editingRound = ref<ReleaseDrillExecutionDto | null>(null); const editingStep = ref<ReleaseDrillStepDto | null>(null)
const roundForm = reactive<ReleaseDrillExecutionWrite>({ releasePlanId: 0, environmentId: 0, roundName: '', plannedAt: '', status: 'PLANNED', resultContent: '', rowVersion: 0 })
const stepForm = reactive({ stepName: '', ownerId: undefined as number | undefined, range: [] as string[], status: 'PENDING', resultContent: '', description: '', rowVersion: 0, seqNo: undefined as number | undefined })
const canManage = () => auth.hasPermission('release-operations:drill:manage')
const selectedRound = () => rounds.value.find(item => item.id === selectedId.value) || rounds.value[0]
const statusLabels: Record<string, string> = { PLANNED: '待演练', RUNNING: '演练中', COMPLETED: '已完成', PENDING: '待开始', SKIPPED: '已跳过' }
function minute(value?: string) { return value ? value.replace('T', ' ').slice(0, 16) : '未安排' }
function isForbidden(cause: unknown) { return (cause as { response?: { status?: number } }).response?.status === 403 }
async function load() { loading.value = true; error.value = ''; forbidden.value = false; try { const [r, p, e, m] = await Promise.all([listReleaseDrills(props.projectId), listReleasePlans(props.projectId), listReleaseDrillEnvironments(props.projectId), listReleaseOperationMemberOptions(props.projectId)]); rounds.value = r.data.data; plans.value = p.data.data; environments.value = e.data.data; members.value = m.data.data; if (!rounds.value.some(item => item.id === selectedId.value)) selectedId.value = rounds.value[0]?.id } catch (cause) { rounds.value = []; error.value = apiErrorMessage(cause, '投产演练加载失败，请稍后重试'); forbidden.value = isForbidden(cause) } finally { loading.value = false } }
function openRound(round?: ReleaseDrillExecutionDto) { editingRound.value = round || null; Object.assign(roundForm, { releasePlanId: round?.releasePlanId || plans.value[0]?.id || 0, environmentId: round?.environmentId || environments.value[0]?.id || 0, roundName: round?.roundName || `第 ${rounds.value.length + 1} 轮演练`, plannedAt: round?.plannedAt || '', status: round?.status || 'PLANNED', resultContent: round?.resultContent || '', rowVersion: round?.rowVersion || 0 }); roundDialog.value = true }
async function saveRound() { if (!roundForm.releasePlanId || !roundForm.environmentId || !roundForm.roundName.trim() || saving.value) return; saving.value = true; try { const response = editingRound.value ? await updateReleaseDrill(props.projectId, editingRound.value.id, { ...roundForm }) : await createReleaseDrill(props.projectId, { ...roundForm }); const value = response.data.data; rounds.value = editingRound.value ? rounds.value.map(item => item.id === value.id ? value : item) : [...rounds.value, value]; selectedId.value = value.id; roundDialog.value = false; ElMessage.success(editingRound.value ? '演练轮次已更新' : '演练轮次已创建') } catch (cause) { ElMessage.error(apiErrorMessage(cause, '演练轮次保存失败，请重试')) } finally { saving.value = false } }
async function removeRound(round: ReleaseDrillExecutionDto) { try { await ElMessageBox.confirm(`将删除“${round.roundName}”，删除后不可恢复。`, '删除演练轮次', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await deleteReleaseDrill(props.projectId, round.id, round.rowVersion); rounds.value = rounds.value.filter(item => item.id !== round.id); selectedId.value = rounds.value[0]?.id; ElMessage.success('演练轮次已删除') } catch (cause) { if (cause !== 'cancel' && cause !== 'close') ElMessage.error(apiErrorMessage(cause, '演练轮次删除失败，请刷新后重试')) } }
function openStep(step?: ReleaseDrillStepDto) { editingStep.value = step || null; Object.assign(stepForm, { stepName: step?.stepName || '', ownerId: step?.ownerId, range: step?.plannedStart && step?.plannedEnd ? [step.plannedStart, step.plannedEnd] : [], status: step?.status || 'PENDING', resultContent: step?.resultContent || '', description: step?.description || '', rowVersion: step?.rowVersion || 0, seqNo: step?.seqNo }); stepDrawer.value = true }
async function saveStep() { const round = selectedRound(); if (!round || !stepForm.stepName.trim() || stepSaving.value) return; stepSaving.value = true; try { const data = { stepName: stepForm.stepName, ownerId: stepForm.ownerId, plannedStart: stepForm.range[0], plannedEnd: stepForm.range[1], status: stepForm.status, resultContent: stepForm.resultContent, description: stepForm.description, rowVersion: stepForm.rowVersion, seqNo: stepForm.seqNo }; const response = editingStep.value ? await updateReleaseDrillStep(props.projectId, round.id, editingStep.value.id, data) : await createReleaseDrillStep(props.projectId, round.id, data); const value = response.data.data; rounds.value = rounds.value.map(item => item.id === round.id ? { ...item, steps: [...item.steps.filter(step => step.id !== value.id), value].sort((a, b) => a.seqNo - b.seqNo) } : item); stepDrawer.value = false; ElMessage.success(editingStep.value ? '演练步骤已更新' : '演练步骤已添加') } catch (cause) { ElMessage.error(apiErrorMessage(cause, '演练步骤保存失败，请重试')) } finally { stepSaving.value = false } }
async function removeStep(step: ReleaseDrillStepDto) { const round = selectedRound(); if (!round) return; try { await ElMessageBox.confirm(`将删除“${step.stepName}”，删除后不可恢复。`, '删除演练步骤', { type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消' }); await deleteReleaseDrillStep(props.projectId, round.id, step.id, step.rowVersion); round.steps = round.steps.filter(item => item.id !== step.id); ElMessage.success('演练步骤已删除') } catch (cause) { if (cause !== 'cancel' && cause !== 'close') ElMessage.error(apiErrorMessage(cause, '演练步骤删除失败，请刷新后重试')) } }
onMounted(load)
</script>

<template>
  <div v-if="forbidden" class="release-operations-state"><el-result icon="warning" title="无权查看投产演练" sub-title="请联系项目管理员申请查看权限。" /></div>
  <div v-else-if="error" class="release-operations-state release-operations-state--error"><el-result icon="error" title="投产演练加载失败" :sub-title="error"><template #extra><el-button type="primary" @click="load">重新加载</el-button></template></el-result></div>
  <div v-else v-loading="loading" class="release-operations-grid release-drill-manager"><section class="release-operations-panel"><header class="release-operations-panel__header"><div><span class="release-operations-kicker">DRILL ROUNDS</span><h2>投产演练</h2><p>每轮演练必须选择投产方案和投产环境。</p></div><div class="release-operations-header-actions"><el-button :icon="Refresh" circle aria-label="刷新投产演练" @click="load" /><el-button v-if="canManage()" type="primary" :icon="Plus" :disabled="!plans.length || !environments.length" @click="openRound()">新增轮次</el-button></div></header><div class="release-operations-panel__body release-plan-list"><UiEmptyState v-if="!rounds.length && !loading" title="暂无演练轮次" description="先准备方案和环境，再新增演练轮次。"><template #action><el-button v-if="canManage()" type="primary" :disabled="!plans.length || !environments.length" @click="openRound()">新增轮次</el-button></template></UiEmptyState><button v-for="round in rounds" v-else :key="round.id" type="button" class="release-plan-list__item" :class="{ 'is-active': selectedRound()?.id === round.id }" @click="selectedId = round.id"><span><strong>第 {{ round.roundNo }} 轮 · {{ round.roundName }}</strong><small>{{ round.releasePlanName }} · {{ round.environmentName }}</small></span><em>{{ round.steps.length }} 步</em></button></div></section><section class="release-operations-panel"><header class="release-operations-panel__header"><div><span class="release-operations-kicker">ROUND DETAIL</span><h2>{{ selectedRound()?.roundName || '选择演练轮次' }}</h2><p v-if="selectedRound()">方案：{{ selectedRound()?.releasePlanName }} · 环境：{{ selectedRound()?.environmentName }} · {{ minute(selectedRound()?.plannedAt) }}</p><p v-else>选择左侧轮次查看演练步骤。</p></div><div v-if="selectedRound() && canManage()" class="release-operations-header-actions"><el-button :icon="Edit" circle aria-label="编辑演练轮次" @click="openRound(selectedRound())" /><el-button :icon="Delete" circle type="danger" aria-label="删除演练轮次" @click="removeRound(selectedRound()!)" /></div></header><div v-if="selectedRound()" class="release-operations-panel__body"><div class="release-plan-section__heading"><div><strong>演练步骤时序</strong><small>{{ selectedRound()?.steps.length }} 个步骤</small></div><el-button v-if="canManage()" type="primary" plain :icon="Plus" @click="openStep()">新增步骤</el-button></div><UiEmptyState v-if="!selectedRound()?.steps.length" title="暂无演练步骤" description="维护本轮演练的执行步骤、时间和结果。" /><div v-else class="release-operations-timeline release-plan-timeline"><div class="release-operations-timeline__track"><article v-for="step in selectedRound()?.steps" :key="step.id" class="release-operations-timeline__item"><div class="release-operations-timeline__dot">{{ step.seqNo }}</div><div class="release-operations-timeline__card"><strong>{{ step.stepName }}</strong><small>{{ minute(step.plannedStart) }} 至 {{ minute(step.plannedEnd) }}</small><small>{{ step.ownerName || '未指定负责人' }} · {{ statusLabels[step.status] || step.status }}</small><p v-if="step.resultContent">结果：{{ step.resultContent }}</p><div v-if="canManage()" class="release-operations-timeline__actions"><el-button link :icon="Edit" aria-label="编辑演练步骤" @click="openStep(step)" /><el-button link type="danger" :icon="Delete" aria-label="删除演练步骤" @click="removeStep(step)" /></div></div></article></div></div></div><UiEmptyState v-else title="请选择演练轮次" description="左侧选择轮次维护演练步骤。" /></section></div>
  <el-dialog v-model="roundDialog" :title="editingRound ? '编辑投产演练轮次' : '新增投产演练轮次'" width="min(680px, 92vw)" destroy-on-close><el-form label-position="top" class="release-operations-form-grid"><el-form-item label="投产方案" required><el-select v-model="roundForm.releasePlanId"><el-option v-for="plan in plans" :key="plan.id" :label="`${plan.planName}（${plan.planCode}）`" :value="plan.id" /></el-select></el-form-item><el-form-item label="投产环境" required><el-select v-model="roundForm.environmentId"><el-option v-for="environment in environments" :key="environment.id" :label="environment.environmentName" :value="environment.id" /></el-select></el-form-item><el-form-item label="轮次名称" required><el-input v-model="roundForm.roundName" maxlength="128" /></el-form-item><el-form-item label="计划时间"><el-date-picker v-model="roundForm.plannedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" /></el-form-item><el-form-item label="状态"><el-select v-model="roundForm.status"><el-option label="待演练" value="PLANNED" /><el-option label="演练中" value="RUNNING" /><el-option label="已完成" value="COMPLETED" /></el-select></el-form-item><el-form-item label="结果记录" class="is-wide"><el-input v-model="roundForm.resultContent" type="textarea" :rows="3" maxlength="2000" /></el-form-item></el-form><template #footer><el-button @click="roundDialog = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!roundForm.releasePlanId || !roundForm.environmentId || !roundForm.roundName.trim()" @click="saveRound">保存</el-button></template></el-dialog>
  <el-drawer v-model="stepDrawer" :title="editingStep ? '编辑演练步骤' : '新增演练步骤'" direction="rtl" size="min(680px, 94vw)" destroy-on-close><el-form label-position="top" class="release-operations-form-grid"><el-form-item label="步骤名称" required class="is-wide"><el-input v-model="stepForm.stepName" maxlength="128" /></el-form-item><el-form-item label="序号"><el-input-number v-model="stepForm.seqNo" :min="1" :max="999" /></el-form-item><el-form-item label="负责人"><el-select v-model="stepForm.ownerId" clearable><el-option v-for="member in members" :key="member.userId" :label="`${member.displayName}（${member.username}）`" :value="member.userId" /></el-select></el-form-item><el-form-item label="计划时间范围" class="is-wide"><el-date-picker v-model="stepForm.range" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" /></el-form-item><el-form-item label="状态"><el-select v-model="stepForm.status"><el-option label="待开始" value="PENDING" /><el-option label="进行中" value="RUNNING" /><el-option label="已完成" value="COMPLETED" /><el-option label="已跳过" value="SKIPPED" /></el-select></el-form-item><el-form-item label="执行结果"><el-input v-model="stepForm.resultContent" maxlength="2000" /></el-form-item><el-form-item label="步骤说明" class="is-wide"><el-input v-model="stepForm.description" type="textarea" :rows="3" maxlength="2000" /></el-form-item></el-form><template #footer><div class="release-drawer-actions"><el-button @click="stepDrawer = false">取消</el-button><el-button type="primary" :loading="stepSaving" :disabled="!stepForm.stepName.trim()" @click="saveStep">保存</el-button></div></template></el-drawer>
</template>
